#!/usr/bin/env python3
import json
import sys
from collections import defaultdict
from pathlib import Path

# This script was generated by ChatGPT
# Save the https://api.jfit.co/models/ as a json file (ie tuple_models.json)
# then run 'python convert_web_model_to_kotlin_map.py tuple_models.json ConsoleToFramePrefixMap.kt'

# Filter on software_configuration_class, not project. Project names are not consistent (ie "TCV, Vortex Lite").
ALLOWED_SW_CLASSES = {
    "chimera",
    "lowcostgui",
    "projectone",
}

def norm(s: str) -> str:
    return (s or "").strip()

def is_valid_prefix(s: str) -> bool:
    s = norm(s).lower()
    return bool(s) and s != "unknown"

def main():
    if len(sys.argv) < 2:
        print("Usage: convert_web_model_to_kotlin_map.py <input.json> [output.kt]")
        sys.exit(1)

    input_path = Path(sys.argv[1])
    output_path = (
        Path(sys.argv[2])
        if len(sys.argv) >= 3
        else input_path.with_suffix(".kt")
    )

    data = json.loads(input_path.read_text(encoding="utf-8"))

    # consolePrefix -> list[(framePrefix, model_name)]
    index = defaultdict(list)
    console_series = {}
    console_sw_class = {}

    for row in data:
        sw_class = norm(row.get("software_configuration_class"))
        if sw_class not in ALLOWED_SW_CLASSES:
            continue

        pp = row.get("prefix_pair") or {}
        console = norm(pp.get("console_serial_prefix"))
        frame = norm(pp.get("frame_serial_prefix"))

        if not (is_valid_prefix(console) and is_valid_prefix(frame)):
            continue

        series = norm(row.get("series"))
        model_name = norm(row.get("model_name"))

        console_series.setdefault(console, series)
        console_sw_class.setdefault(console, sw_class)
        index[console].append((frame, model_name))

    # Kotlin source generation
    lines = [
        "package com.jht.chimera.lib.common.config",
        "",
        "// AUTO-GENERATED FILE. DO NOT EDIT.",
        "// MAKE SURE TO GENERATE THIS MAP WHENEVER A NEW FRAME OR CONSOLE IS ADDED.",
        "// This is used to suggest if there's console and frame prefix is not a valid tuple so it won't break anything.",
        "// Generated by convert_web_model_to_kotlin_map.py located in Tools/PythonScripts",
        "// python convert_web_model_to_kotlin_map.py tuple_models.json ConsoleToFramePrefixMap.kt",
        "// Script converts https://api.jfit.co/models/ json to a Kotlin map for specific 'software_configuration_class' values",
        "",
        "val ConsoleToFramePrefixMap: Map<String, List<String>> = mapOf(",
    ]

    for console in sorted(index.keys()):
        series = console_series.get(console, "")
        sw_class = console_sw_class.get(console, "")
        lines.append(f'    "{console}" to listOf( // software_configuration_class: {sw_class}, series: {series}')

        frames = sorted(index[console], key=lambda x: x[0])
        for frame, model in frames:
            lines.append(f'        "{frame}", // {model}')

        lines.append("    ),")

    lines.append(")")

    output_path.write_text("\n".join(lines), encoding="utf-8")
    print(f"Wrote {output_path}")

if __name__ == "__main__":
    main()
